-- Seed: "Core 2K Sentences" deck (1966 cards) for test_premium@test.com.
-- Same approach as the Core 2K Vocabulary deck: real sentences with
-- kanji whose readings genuinely need the kuromoji tokenizer, so
-- romaji/kana/furigana are left at their column defaults for the
-- app's existing backfillMissingReadings() to fill in correctly via
-- the real /api/romaji conversion. With ~2000 cards, expect the
-- backfill to take a while (sequential, one card at a time, only
-- while the app is open) -- it resumes across sessions if interrupted.
do $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where email = 'test_premium@test.com';
  if v_uid is null then
    raise exception 'test_premium@test.com not found';
  end if;

  on conflict (id) do nothing;
end $$;
